begin;
create extension if not exists pgtap;
select no_plan();
set local natillera.civil_today='2026-10-20';
insert into auth.users(id,email) values('b8080000-0000-4000-8000-000000000001','synthetic-notes@example.test');
insert into public.workspaces(id,name) values('b8080000-0000-4000-8000-000000000002','Synthetic P011 notes');
insert into public.workspace_users(workspace_id,user_id,role) values('b8080000-0000-4000-8000-000000000002','b8080000-0000-4000-8000-000000000001','admin');
insert into public.cycles(id,workspace_id,year,name,starts_on,closes_on,status) values('b8080000-0000-4000-8000-000000000003','b8080000-0000-4000-8000-000000000002',2026,'Synthetic notes','2026-01-01','2026-12-05','active');
insert into public.members(id,workspace_id,display_name) values('b8080000-0000-4000-8000-000000000004','b8080000-0000-4000-8000-000000000002','Synthetic P011 debtor');
insert into public.cycle_members(id,workspace_id,cycle_id,member_id,monthly_quota) values('b8080000-0000-4000-8000-000000000005','b8080000-0000-4000-8000-000000000002','b8080000-0000-4000-8000-000000000003','b8080000-0000-4000-8000-000000000004',10000);
set local request.jwt.claim.sub='b8080000-0000-4000-8000-000000000001';
set local role authenticated;
select public.create_bank_account('b8080000-0000-4000-8000-000000000003','Synthetic notes bank','','');
select public.record_bank_opening('b8080000-0000-4000-8000-000000000003',(select id from bank_accounts where display_name='Synthetic notes bank'),'notes-opening','2026-01-01',1000000,'Synthetic funds');
select public.record_internal_liquidity_transfer('b8080000-0000-4000-8000-000000000003','notes-cash','2026-01-01','bank',(select id from bank_accounts where display_name='Synthetic notes bank'),'cash',null,500000,'Synthetic disbursement');
create temp table notes_loan as select id from public.create_loan_contract('b8080000-0000-4000-8000-000000000003','synthetic-p011','b8080000-0000-4000-8000-000000000004',null,null,500000,'fixed_interest','MONTHLY_FIXED',0.05,4,'2026-06-01');
select public.confirm_loan_disbursement((select id from notes_loan),'notes-disburse','2026-06-01');
select is((select sum(interest_due) from loan_schedules where loan_id=(select id from notes_loan)),100000::numeric,'P011 500k at 5 percent has four contractual 25k interest installments');
select lives_ok($$select public.record_noted_loan_payment((select id from notes_loan),'notes-i1','2026-07-01',25000,0,25000,'regular',(select id from bank_accounts where display_name='Synthetic notes bank'),null,' Interes julio ')$$,'first noted interest receipt enters selected bank');
select is((select note from loan_payments where idempotency_key='notes-i1'),'Interes julio','note normalized and stored on domain receipt');
select lives_ok($$select public.record_noted_loan_payment((select id from notes_loan),'notes-i1','2026-07-01',25000,0,25000,'regular',(select id from bank_accounts where display_name='Synthetic notes bank'),null,'Interes julio')$$,'identical normalized retry is idempotent');
select throws_ok($$select public.record_noted_loan_payment((select id from notes_loan),'notes-i1','2026-07-01',25000,0,25000,'regular',(select id from bank_accounts where display_name='Synthetic notes bank'),null,'Otra nota')$$,'P0001','La clave de idempotencia del cobro ya existe con otra nota.','same key cannot change annotation');
select throws_ok($$select public.record_noted_loan_payment((select id from notes_loan),'notes-i1','2026-07-01',25000,0,25000,'regular',null,null,'Interes julio')$$,'P0001','El destino del cobro no coincide con el intento original.','note wrapper preserves destination idempotency');
select lives_ok($$select public.record_noted_loan_payment((select id from notes_loan),'notes-i2','2026-08-01',25000,0,25000,'regular',(select id from bank_accounts where display_name='Synthetic notes bank'),null,null)$$,'note remains optional');
select lives_ok($$select public.record_noted_loan_payment((select id from notes_loan),'notes-cap','2026-08-02',200000,200000,0,'regular',(select id from bank_accounts where display_name='Synthetic notes bank'),null,repeat('ñ',500))$$,'500 Unicode characters accepted for capital payment');
select is((select char_length(note) from loan_payments where idempotency_key='notes-cap'),500,'limit counts characters rather than UTF8 bytes');
select is((select sum(interest_paid) from loan_schedule_progress where loan_id=(select id from notes_loan)),50000::numeric,'two verified interest applications total 50k');
select is((select sum(principal_paid) from loan_schedule_progress where loan_id=(select id from notes_loan)),200000::numeric,'capital payment applied exactly once');
select is(public.loan_remaining_principal_at((select id from notes_loan),'2026-08-02'),300000::numeric,'remaining principal 300k after extraordinary capital receipt');
select throws_ok($$select public.record_noted_loan_payment((select id from notes_loan),'notes-long','2026-08-03',1,1,0,'regular',null,null,repeat('a',501))$$,'P0001','La nota debe tener maximo 500 caracteres y no contener caracteres de control.','501 characters rejected before monetary effects');
select throws_ok($$select public.record_noted_loan_payment((select id from notes_loan),'notes-control','2026-08-03',1,1,0,'regular',null,null,E'linea\ncontrol')$$,'P0001','La nota debe tener maximo 500 caracteres y no contener caracteres de control.','control characters rejected');
select is((select count(*) from loan_payments where idempotency_key in('notes-long','notes-control')),0::bigint,'invalid notes create no receipts');
update loan_payments set note='Editada' where idempotency_key='notes-i1';
select is((select note from loan_payments where idempotency_key='notes-i1'),'Interes julio','RLS prevents authenticated admin from editing notes via table');
select throws_ok($$select public.record_noted_loan_payment((select id from notes_loan),'notes-bad-bank','2026-08-03',1,1,0,'regular','b8080000-0000-4000-8000-000000000099',null,'Valid note with rejected destination')$$,'P0001','Cuenta bancaria no disponible.','invalid destination aborts complete noted transaction');
select is((select count(*) from loan_payments where idempotency_key='notes-bad-bank'),0::bigint,'failed monetary transaction leaves no note or receipt');
create temp table notes_quote as select public.quote_loan_prepayment((select id from notes_loan),'2026-08-03')q;
select is((select q->>'rule_version' from notes_quote),'contract-fixed-policy','synthetic P011 uses existing fixed contract policy, not P013 agreement');
select is((select (q->>'interest_due')::numeric from notes_quote),0::numeric,'current full-payment policy does not recobrar first interest already satisfied');
select is((select (q->>'total_due')::numeric from notes_quote),300000::numeric,'full-payment quote is remaining capital under existing policy');
select lives_ok($$select public.confirm_noted_loan_prepayment((select id from notes_loan),'notes-full','2026-08-03',(select q->>'quote_hash' from notes_quote),(select id from bank_accounts where display_name='Synthetic notes bank'),'Cancelacion total')$$,'full repayment stores note and selected bank transactionally');
select is((select note from loan_payments where idempotency_key='notes-full'),'Cancelacion total','full repayment persists note');
select is((select status from loan_contracts where id=(select id from notes_loan)),'paid','full repayment closes contract');
select lives_ok($$select public.confirm_noted_loan_prepayment((select id from notes_loan),'notes-full','2026-08-03',(select q->>'quote_hash' from notes_quote),(select id from bank_accounts where display_name='Synthetic notes bank'),'Cancelacion total')$$,'full repayment exact retry works after paid state');
select throws_ok($$select public.confirm_noted_loan_prepayment((select id from notes_loan),'notes-full','2026-08-03',(select q->>'quote_hash' from notes_quote),(select id from bank_accounts where display_name='Synthetic notes bank'),'Alterada')$$,'P0001','La clave de idempotencia del cobro ya existe con otra nota.','full repayment retry cannot change note');
select is((select count(*) from loan_payments where loan_id=(select id from notes_loan)),4::bigint,'only four original payments after retries');
select is((select sum(amount) from ledger_entries where cycle_id='b8080000-0000-4000-8000-000000000003' and account='cash' and liquidity_location='bank'),1050000::numeric,'bank collects principal once plus 50k interest');
select is((select sum(amount) from ledger_entries where cycle_id='b8080000-0000-4000-8000-000000000003' and account='cash' and liquidity_location='cash'),0::numeric,'bank receipts create no physical cash');
select lives_ok($$select public.reverse_financial_operation((select operation_id from loan_payments where idempotency_key='notes-full'),'notes-full-reverse','2026-08-03','Synthetic correction')$$,'full receipt reverses bank and domain state');
select is((select note from loan_payments where idempotency_key='notes-full'),'Cancelacion total','reversal retains immutable original note');
select is((select status from loan_contracts where id=(select id from notes_loan)),'active','reversal reopens contract');
select is(public.loan_remaining_principal_at((select id from notes_loan),'2026-08-03'),300000::numeric,'reversal restores 300k principal without duplicate capital');
select is((select sum(principal_paid) from loan_schedule_progress where loan_id=(select id from notes_loan)),200000::numeric,'reversed full receipt drops only its applications');
select is((select sum(amount) from ledger_entries where cycle_id='b8080000-0000-4000-8000-000000000003' and account='cash' and liquidity_location='bank'),750000::numeric,'bank returns exactly to pre-full-repayment amount');
select lives_ok($$select public.reverse_financial_operation((select operation_id from loan_payments where idempotency_key='notes-full'),'notes-full-reverse','2026-08-03','Synthetic correction')$$,'reversal retry does not duplicate money');
reset role;
select throws_ok($$update loan_payments set note='Edited by owner' where idempotency_key='notes-i1'$$,'P0001','La nota del cobro es inmutable.','trigger prevents owner edits as well as client edits');
select throws_ok($$update loan_payments set note='Added later' where idempotency_key='notes-i2'$$,'P0001','La nota del cobro es inmutable.','historical null note also immutable');
select ok(not has_function_privilege('anon','public.record_noted_loan_payment(uuid,text,date,numeric,numeric,numeric,text,uuid,text,text)','EXECUTE'),'anonymous noted payment forbidden');
select ok(not has_function_privilege('anon','public.confirm_noted_loan_prepayment(uuid,text,date,text,uuid,text)','EXECUTE'),'anonymous noted full repayment forbidden');
set local role authenticated;
set local request.jwt.claim.sub='b8080000-0000-4000-8000-000000000099';
select throws_ok($$select public.record_noted_loan_payment((select id from notes_loan),'notes-outsider','2026-08-03',1,1,0,'regular',null,null,'Unauthorized')$$,'P0001','No tiene permiso sobre este prestamo.','nonmember cannot record annotated receipt');
set local request.jwt.claim.sub='b8080000-0000-4000-8000-000000000001';
reset role;
select is((select count(*) from(select operation_id from ledger_entries where cycle_id='b8080000-0000-4000-8000-000000000003' group by operation_id having sum(amount)<>0)x),0::bigint,'all noted payments and reversals remain balanced');
select * from finish();
rollback;
